// question and the start of the first answer above the screen.  Focus never moves (preventScroll), reduced motion jumps instead of gliding.
function settle(el) {
  const reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  el.scrollIntoView({ behavior: reduce ? 'auto' : 'smooth', block: 'start' });
}

